mapper.select:
SELECT d.diary_id, d.trip_id, d.member_id, d.content, d.visibility, d.status, d.is_ai_generated, d.created_at, d.updated_at FROM diary d
AND (d.status IS NULL OR d.status != 'DELETED')
AND d.member_id = #{memberId}
AND d.trip_id = #{tripId}
AND d.diary_id < #{cursor}
ORDER BY d.diary_id DESC LIMIT #{size}
